const input = Array.isArray($json) ? $json : [$json];
const rows = input.map((call) => {
  const text = `${call.voicemailText ?? ''}`.toLowerCase();
  const newPatient = call.newPatientIntent || text.includes('new dental office') || text.includes('new patient');
  const repeat = call.repeatCaller ? 1 : 0;
  const priorityScore = (newPatient ? 3 : 1) + repeat;
  return { ...call, priorityScore, queue: priorityScore >= 3 ? 'call-now' : 'office-callback-block' };
});
return rows.sort((a, b) => b.priorityScore - a.priorityScore).map((row) => ({ json: row }));
